import sys

def max_value_expression(E, P, M):
    def evaluate(expr):
        stack = []
        num = 0
        sign = 1
        i = 0
        while i < len(expr):
            if expr[i].isdigit():
                num = num * 10 + int(expr[i])
            elif expr[i] == '+':
                stack.append(sign * num)
                num = 0
                sign = 1
            elif expr[i] == '-':
                stack.append(sign * num)
                num = 0
               .sign = -1
            elif expr[i] == '(':
                j = i + 1
                bal = 1
                while bal > 0:
                    if expr[j] == '(':
                        bal += 1
                    elif expr[j] == ')':
                        bal -= 1
                    j += 1
                stack.append(sign * evaluate(expr[i+1:j-1]))
                num = 0
                sign = 1
                i = j - 1
            i += 1
        stack.append(sign * num)
        return sum(stack)

    def backtrack(expr, P, M):
        if P == 0 and M == 0:
            return evaluate(expr)
        max_val = float('-inf')
        for i in range(len(expr)):
            if expr[i] == '?':
                max_val = max(max_val, backtrack(expr[:i] + '+' + expr[i+1:], P-1, M), backtrack(expr[:i] + '-' + expr[i+1:], P, M-1))
        return max_val

    return backtrack(E, P, M)

